insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('hyphessobrycon-amandae','Ember Tetra','Hyphessobrycon amandae','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Turuncu-kızıl rengi ve 2 cm civarındaki boyuyla nano akvaryumların sevilen sürü balıklarındandır. Koyu tabanlı, bitkili tanklarda rengi belirginleşir.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya, Araguaia havzası"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, Sürü Balığı"]]'::jsonb,array['ember tetra','hyphessobrycon amandae','amandae','kor tetra']::text[],false,'published'),
('petitella-rhodostoma','Rummy Nose Tetra','Petitella rhodostoma','characiformlar','fish','Orta','Barışçıl, sürü balığı','Kırmızı burun ve siyah-beyaz kuyruk deseniyle çok dikkat çekici bir sürü balığıdır. Stabil ve temiz su koşullarında sıkı sürü davranışı gösterir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü Balığı, Hassas"]]'::jsonb,array['rummy nose tetra','petitella rhodostoma','rummynose tetra','rummy nose','rhodostoma']::text[],false,'published'),
('hemigrammus-erythrozonus','Glowlight Tetra','Hemigrammus erythrozonus','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Gövdesi boyunca uzanan parlak turuncu çizgiyle tanınır. Sakin, bitkili ve hafif asidik topluluk akvaryumlarına uygundur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Guyana"], ["Ömür", "4–5 yıl"], ["Özellikler", "Sürü Balığı, Parlak"]]'::jsonb,array['glowlight tetra','hemigrammus erythrozonus','erythrozonus','ışıklı tetra']::text[],false,'published'),
('hyphessobrycon-pulchripinnis','Limon Tetra','Hyphessobrycon pulchripinnis','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Sarı tonları, kırmızı göz üstü ve siyah-sarı yüzgeçleriyle klasik bir tetra türüdür. Kalabalık grupta daha güvenli ve renkli görünür.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya, Tapajós havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü Balığı, Sarı"]]'::jsonb,array['lemon tetra','hyphessobrycon pulchripinnis','limon tetra','pulchripinnis']::text[],false,'published'),
('hyphessobrycon-eques','Serpae Tetra','Hyphessobrycon eques','characiformlar','fish','Kolay','Hareketli, yarı agresif','Kırmızı gövdesiyle gösterişli fakat zaman zaman yüzgeç didikleyebilen hareketli bir tetra türüdür. Kalabalık grup agresyonu dağıtmaya yardımcı olur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.0–7.8"], ["Min. akvaryum", "70 L"], ["Huy", "Hareketli, yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Güney Amerika"], ["Ömür", "4–6 yıl"], ["Özellikler", "Kırmızı, Sürü Balığı"]]'::jsonb,array['serpae tetra','hyphessobrycon eques','red minor tetra','serpa tetra']::text[],false,'published'),
('pristella-maxillaris','Pristella Tetra','Pristella maxillaris','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Şeffaf gövdesi ve sarı-siyah yüzgeçleriyle dayanıklı bir topluluk balığıdır. Geniş su parametresi toleransı yeni başlayanlar için avantaj sağlar.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Venezuela–Guyana–Brezilya"], ["Ömür", "4–5 yıl"], ["Özellikler", "Dayanıklı, Sürü Balığı"]]'::jsonb,array['pristella maxillaris','x ray tetra','pristella tetra','pristella']::text[],false,'published'),
('nematobrycon-palmeri','İmparator Tetra','Nematobrycon palmeri','characiformlar','fish','Orta','Barışçıl, erkekler rekabetçi','Mor-mavi yansımaları ve erkeklerde uzayan kuyruk ışınlarıyla zarif bir tetra türüdür. Erkekler küçük bölgeler tutsa da genel olarak topluluk balığıdır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.0–7.8"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, erkekler rekabetçi"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Kolombiya"], ["Ömür", "5–6 yıl"], ["Özellikler", "Renkli, Sürü Balığı"]]'::jsonb,array['emperor tetra','nematobrycon palmeri','imparator tetra','palmeri']::text[],false,'published'),
('phenacogrammus-interruptus','Kongo Tetra','Phenacogrammus interruptus','characiformlar','fish','Orta','Barışçıl, aktif sürü','Erkeklerin gökkuşağı renkleri ve uzun yüzgeçleriyle büyük ve gösterişli bir Afrika tetrasıdır. Uzun yüzme alanı ve kalabalık grup ister.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Kongo Havzası"], ["Ömür", "5–8 yıl"], ["Özellikler", "Afrika Tetrası, Renkli"]]'::jsonb,array['congo tetra','phenacogrammus interruptus','kongo tetra','interruptus']::text[],false,'published'),
('thayeria-boehlkei','Penguen Tetra','Thayeria boehlkei','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Eğik yüzüşü ve gövde boyunca kuyruğa uzanan siyah çizgisiyle kolay tanınır. Aktif ve barışçıl bir sürü balığıdır.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon Havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü Balığı, Aktif"]]'::jsonb,array['penguin tetra','thayeria boehlkei','hockey stick tetra','penguen tetra']::text[],false,'published'),
('moenkhausia-pittieri','Elmas Tetra','Moenkhausia pittieri','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Işık altında parlayan pulları ve morumsu yüzgeçleriyle dikkat çeker. Olgun bireyler gençlere göre çok daha gösterişli olur.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Venezuela, Valencia Gölü"], ["Ömür", "4–6 yıl"], ["Özellikler", "Parlak, Sürü Balığı"]]'::jsonb,array['diamond tetra','moenkhausia pittieri','elmas tetra','pittieri']::text[],false,'published'),
('psalidodon-anisitsi','Buenos Aires Tetra','Psalidodon anisitsi','characiformlar','fish','Kolay','Aktif, zaman zaman yüzgeç didikleyici','Çok dayanıklı ve hareketli bir tetra türüdür. Bitkileri yiyebildiği ve küçük tanklarda hareketliliği baskın olduğu için geniş hacim tercih edilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Aktif, zaman zaman yüzgeç didikleyici"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Paraná–Paraguay havzası"], ["Ömür", "5–6 yıl"], ["Özellikler", "Dayanıklı, Aktif"]]'::jsonb,array['buenos aires tetra','psalidodon anisitsi','hyphessobrycon anisitsi','anisitsi']::text[],false,'published'),
('moenkhausia-sanctaefilomenae','Kırmızı Göz Tetra','Moenkhausia sanctaefilomenae','characiformlar','fish','Kolay','Barışçıl, aktif sürü','Parlak kırmızı göz üstü ve kuyruk tabanındaki siyah lekeyle tanınır. Dayanıklı, aktif ve grup hâlinde bakılması gereken bir türdür.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "90 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Güney Amerika"], ["Ömür", "5 yıl"], ["Özellikler", "Dayanıklı, Sürü Balığı"]]'::jsonb,array['red eye tetra','moenkhausia sanctaefilomenae','red eyed tetra','kırmızı göz tetra']::text[],false,'published'),
('hyphessobrycon-herbertaxelrodi','Siyah Neon Tetra','Hyphessobrycon herbertaxelrodi','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Siyah ve parlak açık renkli yatay çizgileriyle neonlardan farklı bir görünüm sunar. Dayanıklı ve barışçıl sürü balığıdır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya, Paraguay havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü Balığı, Kontrast"]]'::jsonb,array['siyah neon tetra','black neon tetra','hyphessobrycon herbertaxelrodi','siyah neon','herbertaxelrodi']::text[],false,'published'),
('paracheirodon-simulans','Yeşil Neon Tetra','Paracheirodon simulans','characiformlar','fish','Orta','Barışçıl, sürü balığı','Kardinal ve neon tetradan daha küçük, mavi-yeşil çizgisi baskın bir türdür. Çok yumuşak ve asidik su koşullarında doğal görünümünü sergiler.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "4.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Rio Negro–Orinoco"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, Siyah Su"]]'::jsonb,array['yeşil neon tetra','green neon tetra','paracheirodon simulans','simulans','yeşil neon']::text[],true,'published'),
('hyphessobrycon-sweglesi','Kırmızı Fantom Tetra','Hyphessobrycon sweglesi','characiformlar','fish','Orta','Barışçıl, sürü balığı','Kırmızı gövdesi ve belirgin humeral lekesiyle küçük, zarif bir sürü balığıdır. Hafif serin ve yumuşak suyu sever.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Kolombiya–Venezuela"], ["Ömür", "4–5 yıl"], ["Özellikler", "Kırmızı, Sürü Balığı"]]'::jsonb,array['kırmızı fantom tetra','red phantom tetra','hyphessobrycon sweglesi','kırmızı fantom','sweglesi']::text[],false,'published'),
('hyphessobrycon-megalopterus','Siyah Fantom Tetra','Hyphessobrycon megalopterus','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Erkeklerde büyük koyu yüzgeçler ve dişilerde kızıl tonlarla belirgin cinsiyet farkı gösterir. Sakin sürü düzenine uygundur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya–Bolivya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Sürü Balığı, Dimorfik"]]'::jsonb,array['siyah fantom tetra','black phantom tetra','megalamphodus megalopterus','hyphessobrycon megalopterus','siyah fantom']::text[],false,'published'),
('hyphessobrycon-rosaceus','Rosy Tetra','Hyphessobrycon rosaceus','characiformlar','fish','Orta','Barışçıl, sürü balığı','Pembe-kırmızı tonları ve beyaz uçlu yüzgeçleriyle gösterişli bir küçük tetradır. Sakin topluluklarda grup hâlinde tutulmalıdır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Guyana–Brezilya"], ["Ömür", "4–5 yıl"], ["Özellikler", "Pembe, Sürü Balığı"]]'::jsonb,array['rosy tetra','hyphessobrycon rosaceus','rosaceus','pembe tetra']::text[],false,'published'),
('hyphessobrycon-erythrostigma','Bleeding Heart Tetra','Hyphessobrycon erythrostigma','characiformlar','fish','Orta','Barışçıl, sürü balığı','Gövdenin ortasındaki kırmızı ''kalp'' lekesiyle tanınan orta boy bir tetradır. Geniş grup ve sakin tank arkadaşlarıyla iyi sonuç verir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon Havzası"], ["Ömür", "5–7 yıl"], ["Özellikler", "Kalp Lekeli, Sürü Balığı"]]'::jsonb,array['bleeding heart tetra','hyphessobrycon erythrostigma','erythrostigma','kanayan kalp tetra']::text[],false,'published'),
('hyphessobrycon-columbianus','Kolombiya Tetra','Hyphessobrycon columbianus','characiformlar','fish','Orta','Aktif, yarı agresif','Metalik mavi gövde ve kırmızı yüzgeçleriyle oldukça renkli bir tetradır. Aktif yapısı nedeniyle küçük ve çok sakin balıklarla dikkatli eşleştirilmelidir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "100 L"], ["Huy", "Aktif, yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Kolombiya"], ["Ömür", "5 yıl"], ["Özellikler", "Renkli, Aktif"]]'::jsonb,array['colombian tetra','hyphessobrycon columbianus','columbian redfin tetra','kolombiya tetra']::text[],false,'published'),
('boehlkea-fredcochui','Cochu Mavi Tetra','Boehlkea fredcochui','characiformlar','fish','Orta','Aktif, sürü balığı','Parlak mavi yansımalarıyla dikkat çeken hızlı ve aktif bir sürü balığıdır. Uzun yüzme alanı ve oksijenli su tercih eder.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Aktif, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon Havzası"], ["Ömür", "4–5 yıl"], ["Özellikler", "Mavi, Aktif"]]'::jsonb,array['cochu mavi tetra','blue tetra','boehlkea fredcochui','cochu blue tetra','fredcochui']::text[],true,'published'),
('inpaichthys-kerri','Kral Tetra','Inpaichthys kerri','characiformlar','fish','Orta','Barışçıl, erkekler rekabetçi','Mor-mavi metalik çizgisi ve küçük boyuyla bitkili akvaryumlarda dikkat çeker. Sakin fakat erkekler arasında gösteri davranışı görülebilir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, erkekler rekabetçi"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya, Aripuanã havzası"], ["Ömür", "4–5 yıl"], ["Özellikler", "Mavi, Sürü Balığı"]]'::jsonb,array['kral tetra','inpaichthys kerri','royal tetra','blue emperor tetra','kerri tetra']::text[],false,'published'),
('prionobrama-filigera','Cam Tetra','Prionobrama filigera','characiformlar','fish','Kolay','Barışçıl, aktif sürü','Şeffaf gövdesi ve kırmızı kuyruğuyla zarif, hızlı yüzen bir sürü balığıdır. Üst-orta su seviyesinde geniş yüzme alanını sever.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon Havzası"], ["Ömür", "4–5 yıl"], ["Özellikler", "Şeffaf, Sürü Balığı"]]'::jsonb,array['cam tetra','glass bloodfin tetra','prionobrama filigera','glass tetra','filigera']::text[],false,'published'),
('aphyocharax-anisitsi','Bloodfin Tetra','Aphyocharax anisitsi','characiformlar','fish','Kolay','Barışçıl, aktif sürü','Gümüş gövde ve kırmızı yüzgeçleriyle dayanıklı, hareketli bir sürü balığıdır. Serin tropikal sıcaklıklara toleransı yüksektir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Paraná havzası"], ["Ömür", "5–7 yıl"], ["Özellikler", "Dayanıklı, Kırmızı Yüzgeç"]]'::jsonb,array['bloodfin tetra','aphyocharax anisitsi','bloodfin','kırmızı yüzgeç tetra']::text[],false,'published'),
('exodon-paradoxus','Bucktooth Tetra','Exodon paradoxus','characiformlar','fish','Zor','Agresif, pul yiyici','Keskin dişleri ve pul yeme davranışıyla sıradan topluluk tetrası değildir. Çok kalabalık tür grubu ve geniş tank gerektirir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif, pul yiyici"], ["Beslenme", "Etçil, lepidofag"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon–Orinoco"], ["Ömür", "8–10 yıl"], ["Özellikler", "Agresif, Özel Tür"]]'::jsonb,array['exodon paradoxus','bucktooth tetra','exodon','scale eater tetra']::text[],true,'published'),
('arnoldichthys-spilopterus','Afrika Kırmızı Göz Tetra','Arnoldichthys spilopterus','characiformlar','fish','Orta','Barışçıl, aktif sürü','İri pulları, kırmızı gözleri ve erkeklerdeki renkli anal yüzgeciyle gösterişli Batı Afrika türüdür. Aktif sürü için uzun tank gerekir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Nijerya"], ["Ömür", "5–7 yıl"], ["Özellikler", "Afrika Tetrası, Sürü Balığı"]]'::jsonb,array['afrika kırmızı göz tetra','arnoldichthys spilopterus','african red eye tetra','niger tetra','spilopterus']::text[],true,'published'),
('alestopetersius-brichardi','Kırmızı Kongo Tetra','Alestopetersius brichardi','characiformlar','fish','Zor','Barışçıl, aktif sürü','Erkeklerde kırmızı ve metalik renklerin geliştiği nadir bir Kongo tetra akrabasıdır. Temiz, oksijenli ve geniş yüzme alanı ister.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Kongo Havzası"], ["Ömür", "5–7 yıl"], ["Özellikler", "Afrika Tetrası, Nadir Tür"]]'::jsonb,array['kırmızı kongo tetra','alestopetersius brichardi','red congo tetra','brichardi tetra','alestopetersius']::text[],true,'published'),
('aphyocharax-paraguayensis','Dawn Tetra','Aphyocharax paraguayensis','characiformlar','fish','Orta','Aktif, sürü balığı','Küçük, gümüş renkli ve yüzgeçlerinde kırmızı tonlar bulunan hareketli bir sürü balığıdır. Kalabalık grup yüzgeç didiklemeyi azaltabilir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Aktif, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Paraguay–Paraná havzası"], ["Ömür", "4–5 yıl"], ["Özellikler", "Sürü Balığı, Aktif"]]'::jsonb,array['aphyocharax paraguayensis','dawn tetra','paraguay tetra','paraguayensis']::text[],true,'published'),
('hyphessobrycon-heliacus','Kitty Tetra','Hyphessobrycon heliacus','characiformlar','fish','Orta','Barışçıl, sürü balığı','Sarı-altın tonları ve erkeklerde uzayan yüzgeçleriyle dikkat çeken küçük bir tetra türüdür. Bitkili ve sakin tanklarda grup hâlinde tutulur.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya"], ["Ömür", "4–5 yıl"], ["Özellikler", "Sarı, Nadir Tür"]]'::jsonb,array['hyphessobrycon heliacus','kitty tetra','heliacus tetra','kitty tetra']::text[],true,'published'),
('hyphessobrycon-amapaensis','Amapa Tetra','Hyphessobrycon amapaensis','characiformlar','fish','Orta','Barışçıl, sürü balığı','Gümüş gövdesi boyunca uzanan kırmızı ve siyah çizgilerle zarif bir görünüm sunar. Yumuşak ve hafif asidik suda daha iyi renklenir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya, Amapá"], ["Ömür", "4–5 yıl"], ["Özellikler", "Nadir Tür, Sürü Balığı"]]'::jsonb,array['hyphessobrycon amapaensis','amapa tetra','amapaensis','red line tetra']::text[],true,'published'),
('hyphessobrycon-flammeus','Flame Tetra','Hyphessobrycon flammeus','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Arka gövdesindeki yoğun kırmızı renk nedeniyle alev tetra adıyla bilinir. Sakin, bitkili topluluk akvaryumlarına uygun klasik bir türdür.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya"], ["Ömür", "4–5 yıl"], ["Özellikler", "Kırmızı, Sürü Balığı"]]'::jsonb,array['flame tetra','hyphessobrycon flammeus','von rio tetra','alev tetra']::text[],false,'published'),
('hasemania-nana','Silvertip Tetra','Hasemania nana','characiformlar','fish','Kolay','Aktif, sürü balığı','Bakır-altın gövdesi ve beyaz yüzgeç uçlarıyla aktif bir küçük tetradır. Kalabalık sürüde tutulması yüzgeç didikleme eğilimini azaltır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Aktif, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Brezilya"], ["Ömür", "4–5 yıl"], ["Özellikler", "Aktif, Sürü Balığı"]]'::jsonb,array['silvertip tetra','hasemania nana','copper tetra','silver tip tetra']::text[],false,'published'),
('hemigrammus-ocellifer','Head and Tail Light Tetra','Hemigrammus ocellifer','characiformlar','fish','Kolay','Barışçıl, sürü balığı','Baş ve kuyruk bölgesindeki yansıtıcı lekelerle kolay ayırt edilir. Dayanıklı, sakin ve klasik bir topluluk tetrasıdır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon–Guyana"], ["Ömür", "4–5 yıl"], ["Özellikler", "Dayanıklı, Sürü Balığı"]]'::jsonb,array['hemigrammus ocellifer','head and tail light tetra','beacon tetra','ocellifer']::text[],false,'published')
insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('corydoras-panda','Panda Corydoras','Corydoras panda','kedi-baliklari','fish','Kolay','Barışçıl, sosyal','Göz ve kuyruk tabanındaki siyah lekeleriyle popüler küçük bir dip balığıdır. En az 6 bireylik gruplarda ve ince kum üzerinde tutulmalıdır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Peru"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sosyal, Dip Balığı"]]'::jsonb,array['corydoras panda','panda cory','panda çöpçü','panda corydoras']::text[],false,'published'),
('corydoras-sterbai','Sterbai Corydoras','Corydoras sterbai','kedi-baliklari','fish','Kolay','Barışçıl, sosyal','Beyaz benekli koyu başı ve turuncu pektoral yüzgeçleriyle gösterişli bir Corydoras''tır. Sıcak suya toleransı nedeniyle discus tanklarında da tercih edilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Brezilya–Bolivya"], ["Ömür", "5–10 yıl"], ["Özellikler", "Sosyal, Sıcak Su"]]'::jsonb,array['sterbai corydoras','corydoras sterbai','sterbai cory','sterbai çöpçü','sterbai']::text[],false,'published'),
('corydoras-julii','Julii Corydoras','Corydoras julii','kedi-baliklari','fish','Kolay','Barışçıl, sosyal','İnce benek ve ağ desenleriyle tanınan küçük bir Corydoras türüdür. Ticarette C. trilineatus ile sık karıştırılır.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Brezilya"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sosyal, Benekli"]]'::jsonb,array['julii corydoras','corydoras julii','julii cory','julii çöpçü','leopard cory']::text[],false,'published'),
('corydoras-trilineatus','Üç Çizgili Corydoras','Corydoras trilineatus','kedi-baliklari','fish','Kolay','Barışçıl, sosyal','Julii Corydoras''a benzeyen ağsı baş deseni ve yan çizgisiyle tanınır. Grup hâlinde hareketli ve barışçıl bir dip balığıdır.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Amazon Havzası"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sosyal, Benekli"]]'::jsonb,array['üç çizgili corydoras','corydoras trilineatus','three stripe cory','false julii','trilineatus']::text[],false,'published'),
('corydoras-adolfoi','Adolfoi Corydoras','Corydoras adolfoi','kedi-baliklari','fish','Orta','Barışçıl, sosyal','Turuncu ense bandı ve siyah göz-kuyruk çizgisiyle çok çekici bir Rio Negro Corydoras''ıdır. Yumuşak ve temiz suyu sever.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Brezilya, Rio Negro"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sosyal, Nadir Tür"]]'::jsonb,array['adolfoi corydoras','corydoras adolfoi','adolfoi cory','adolfoi çöpçü','orange crown cory']::text[],true,'published'),
('corydoras-duplicareus','Duplicareus Corydoras','Corydoras duplicareus','kedi-baliklari','fish','Orta','Barışçıl, sosyal','Adolfoi''ye benzeyen fakat daha geniş siyah sırt bandıyla ayırt edilen gösterişli bir türdür. Yumuşak-asidik su koşullarını tercih eder.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Brezilya, Rio Negro"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sosyal, Nadir Tür"]]'::jsonb,array['duplicareus corydoras','corydoras duplicareus','duplicareus cory','adolfoi type cory','duplicareus']::text[],true,'published'),
('corydoras-pygmaeus','Pygmy Corydoras','Corydoras pygmaeus','kedi-baliklari','fish','Kolay','Barışçıl, sürü balığı','Çok küçük boyu ve orta su seviyesinde de sürü hâlinde yüzmesiyle farklı bir Corydoras''tır. Nano topluluklar için uygundur.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "35 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Brezilya"], ["Ömür", "4–6 yıl"], ["Özellikler", "Nano, Sosyal"]]'::jsonb,array['pygmy corydoras','corydoras pygmaeus','pygmy cory','cüce çöpçü','pygmaeus']::text[],false,'published'),
('corydoras-habrosus','Habrosus Corydoras','Corydoras habrosus','kedi-baliklari','fish','Kolay','Barışçıl, sosyal','Küçük boylu fakat pygmaeus''a göre daha çok dipte yaşayan bir cüce Corydoras''tır. İnce kum ve kalabalık grup tercih eder.','[["Yetişkin boy", "3,5 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Mikro dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Orinoco Havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Nano, Dip Balığı"]]'::jsonb,array['habrosus corydoras','corydoras habrosus','salt and pepper cory','habrosus','dwarf cory']::text[],false,'published'),
('corydoras-hastatus','Hastatus Corydoras','Corydoras hastatus','kedi-baliklari','fish','Orta','Barışçıl, sürü balığı','Kuyruk tabanındaki belirgin siyah-beyaz lekeyle tanınan minik Corydoras''tır. Orta su seviyesinde sürü davranışı gösterebilir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "35 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro yemler"], ["Üreme", "Yumurta dökücü"], ["Köken", "Güney Amerika"], ["Ömür", "4–6 yıl"], ["Özellikler", "Nano, Sürü Balığı"]]'::jsonb,array['hastatus corydoras','corydoras hastatus','dwarf cory','tail spot cory','hastatus']::text[],true,'published'),
('corydoras-aeneus','Bronz Corydoras','Corydoras aeneus','kedi-baliklari','fish','Kolay','Barışçıl, sosyal','Dayanıklılığı ve uyum yeteneğiyle en klasik Corydoras türlerinden biridir. Grup hâlinde, ince kumlu dipte aktif biçimde yem arar.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "21–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "70 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor dip yemleri"], ["Üreme", "Yumurta dökücü"], ["Köken", "Güney Amerika"], ["Ömür", "5–10 yıl"], ["Özellikler", "Dayanıklı, Sosyal"]]'::jsonb,array['bronz corydoras','corydoras aeneus','bronze cory','bronz çöpçü','aeneus']::text[],false,'published'),
('panaque-nigrolineatus','Royal Panaque','Panaque nigrolineatus','kedi-baliklari','fish','Zor','Barışçıl, bölgeci','Çizgili gövdesi ve odun kazıma davranışıyla iri bir Loricariid''dir. Büyük tank, güçlü filtrasyon ve gerçek odun materyali ister.','[["Yetişkin boy", "40 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Odun, bitkisel ve omnivor yemler"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Orinoco Havzası"], ["Ömür", "15+ yıl"], ["Özellikler", "Loricariid, İri Yapılı"]]'::jsonb,array['panaque nigrolineatus','royal pleco','royal panaque','l190']::text[],true,'published'),
('hypancistrus-zebra','Zebra Pleco L046','Hypancistrus zebra','kedi-baliklari','fish','Zor','Barışçıl, bölgeci','Siyah-beyaz zebra deseniyle dünyanın en tanınan L-numara vatozlarından biridir. Sıcak, oksijenli su ve etçil ağırlıklı beslenme ister.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "27–31 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "10+ yıl"], ["Özellikler", "L046, Nadir Tür"]]'::jsonb,array['zebra pleco l046','hypancistrus zebra','l046','zebra pleco','zebra vatoz']::text[],true,'published'),
('hypancistrus-sp-l260','Queen Arabesque L260','Hypancistrus sp. L260','kedi-baliklari','fish','Zor','Barışçıl, bölgeci','İnce siyah-beyaz arabesk çizgileriyle gösterişli bir Hypancistrus formudur. Mağaralı, oksijenli ve sıcak akvaryumları tercih eder.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Xingu sistemi"], ["Ömür", "10+ yıl"], ["Özellikler", "L260, Nadir Tür"]]'::jsonb,array['queen arabesque l260','l260','queen arabesque pleco','hypancistrus l260','arabesque vatoz']::text[],true,'published'),
('baryancistrus-xanthellus','Gold Nugget Pleco L018','Baryancistrus xanthellus','kedi-baliklari','fish','Zor','Barışçıl, bölgeci','Siyah gövde üzerindeki sarı benekler ve sarı yüzgeç kenarlarıyla çok gösterişlidir. Güçlü akıntı, yüksek oksijen ve bitkisel ağırlıklı beslenme ister.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Aufwuchs, bitkisel ağırlıklı omnivor"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "10–15 yıl"], ["Özellikler", "L018, Benekli"]]'::jsonb,array['gold nugget pleco l018','baryancistrus xanthellus','l018','gold nugget pleco','golden nugget vatoz']::text[],true,'published'),
('hypancistrus-contradens','Snowball Pleco L201','Hypancistrus contradens','kedi-baliklari','fish','Orta','Barışçıl, bölgeci','Koyu gövde üzerindeki beyaz benekleriyle küçük-orta boy gösterişli bir vatozdur. Protein ağırlıklı beslenir ve mağaraları sever.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Venezuela, Orinoco"], ["Ömür", "10+ yıl"], ["Özellikler", "Benekli, L-numara"]]'::jsonb,array['snowball pleco l201','hypancistrus contradens','l201','snowball pleco','orinoco angel pleco']::text[],true,'published'),
('panaqolus-maccus','Clown Pleco','Panaqolus maccus','kedi-baliklari','fish','Kolay','Barışçıl, bölgeci','Küçük boyu ve açık-koyu bantlarıyla ev akvaryumlarına uygun bir odun yiyici Loricariid''dir. Kök ve saklanma alanı bulunması önemlidir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Odun, bitkisel ve omnivor yemler"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Venezuela–Kolombiya"], ["Ömür", "8–10 yıl"], ["Özellikler", "Küçük Pleco, Odun Yiyici"]]'::jsonb,array['panaqolus maccus','clown pleco','l104','palyaço vatoz']::text[],false,'published'),
('rineloricaria-lanceolata','Whiptail Catfish','Rineloricaria lanceolata','kedi-baliklari','fish','Kolay','Barışçıl','İnce, dal benzeri vücuduyla sakin ve ilginç bir Loricariid''dir. İnce kum, kökler ve sakin tank arkadaşlarıyla iyi yaşar.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, alg/biofilm katkılı"], ["Üreme", "Yumurta koruyucu"], ["Köken", "Güney Amerika"], ["Ömür", "8–10 yıl"], ["Özellikler", "İnce Yapılı, Barışçıl"]]'::jsonb,array['rineloricaria lanceolata','whiptail catfish','whiptail pleco','rineloricaria']::text[],false,'published'),
('farlowella-acus','Twig Catfish','Farlowella acus','kedi-baliklari','fish','Zor','Barışçıl, hassas','Dal görünümündeki kamuflajıyla çok sıra dışı bir vatozdur. Olgun akvaryum, bol biofilm ve sakin tank arkadaşları ister.','[["Yetişkin boy", "16 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Alg, biofilm, bitkisel yemler"], ["Üreme", "Yumurta koruyucu"], ["Köken", "Güney Amerika"], ["Ömür", "8–10 yıl"], ["Özellikler", "Kamuflaj, Hassas"]]'::jsonb,array['farlowella acus','twig catfish','farlowella','dal vatoz']::text[],true,'published'),
('kryptopterus-vitreolus','Cam Kedi Balığı','Kryptopterus vitreolus','kedi-baliklari','fish','Orta','Barışçıl, sürü balığı','Neredeyse tamamen şeffaf gövdesiyle eşsiz bir sürü kedi balığıdır. Sakin, bitkili ve loş tanklarda en az 6–8 birey tutulmalıdır.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Omnivor, küçük yemler"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Tayland"], ["Ömür", "5–8 yıl"], ["Özellikler", "Şeffaf, Sürü Balığı"]]'::jsonb,array['kryptopterus vitreolus','glass catfish','cam kedi balığı','ghost catfish']::text[],false,'published'),
('pimelodus-pictus','Pictus Kedi Balığı','Pimelodus pictus','kedi-baliklari','fish','Orta','Aktif, yırtıcı eğilimli','Benekli gövdesi ve çok uzun bıyıklarıyla hızlı, hareketli bir Güney Amerika kedi balığıdır. Küçük balıkları yutabileceği için tank arkadaşı boyutu önemlidir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Aktif, yırtıcı eğilimli"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Amazon–Orinoco"], ["Ömür", "8–10 yıl"], ["Özellikler", "Benekli, Aktif"]]'::jsonb,array['pictus kedi balığı','pimelodus pictus','pictus catfish','pictus','benekli kedi balığı']::text[],false,'published'),
('phractocephalus-hemioliopterus','Redtail Catfish','Phractocephalus hemioliopterus','kedi-baliklari','fish','Zor','Yırtıcı, iri','Kırmızı kuyruğu ve dev boyutuyla etkileyici fakat ev akvaryumlarının çoğuna uygun olmayan bir yırtıcıdır. Çok büyük özel sistem gerektirir.','[["Yetişkin boy", "120 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "3000 L"], ["Huy", "Yırtıcı, iri"], ["Beslenme", "Etçil"], ["Üreme", "Akvaryumda çok zor"], ["Köken", "Amazon–Orinoco"], ["Ömür", "15–20+ yıl"], ["Özellikler", "Dev Balık, Yırtıcı"]]'::jsonb,array['redtail catfish','phractocephalus hemioliopterus','rtc','kırmızı kuyruk kedi balığı']::text[],false,'published'),
('pseudoplatystoma-fasciatum','Tiger Shovelnose','Pseudoplatystoma fasciatum','kedi-baliklari','fish','Zor','Yırtıcı, iri','Uzun burunlu, çizgili ve çok büyük bir Güney Amerika yırtıcı kedi balığıdır. Yalnızca dev akvaryum veya havuz ölçeğinde düşünülmelidir.','[["Yetişkin boy", "100 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "2500 L"], ["Huy", "Yırtıcı, iri"], ["Beslenme", "Etçil"], ["Üreme", "Akvaryumda çok zor"], ["Köken", "Güney Amerika"], ["Ömür", "15+ yıl"], ["Özellikler", "Dev Balık, Yırtıcı"]]'::jsonb,array['pseudoplatystoma fasciatum','tiger shovelnose','tiger catfish','shovelnose catfish']::text[],false,'published'),
('synodontis-eupterus','Featherfin Synodontis','Synodontis eupterus','kedi-baliklari','fish','Kolay','Yarı agresif, gececi','Büyük ve yelkenimsi sırt yüzgeciyle tanınan dayanıklı Afrika kedi balığıdır. Saklanma alanları ve orta-büyük tank arkadaşları ister.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Yarı agresif, gececi"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Nil–Çad havzaları"], ["Ömür", "10–15 yıl"], ["Özellikler", "Afrika, Gececi"]]'::jsonb,array['synodontis eupterus','featherfin squeaker','featherfin synodontis','eupterus']::text[],false,'published'),
('synodontis-multipunctatus','Cuckoo Catfish','Synodontis multipunctatus','kedi-baliklari','fish','Orta','Sosyal, aktif','Tanganyika cikletlerinin ağızda kuluçka davranışını kullanarak yumurtalarını onlara büyüttüren ünlü kuluçka parazitidir. Sert-alkali suya uygundur.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Sosyal, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Kuluçka paraziti"], ["Köken", "Tanganyika Gölü"], ["Ömür", "10–15 yıl"], ["Özellikler", "Tanganyika, Kuluçka Paraziti"]]'::jsonb,array['synodontis multipunctatus','cuckoo catfish','cuckoo synodontis','multipunctatus']::text[],true,'published'),
('synodontis-petricola','Synodontis petricola','Synodontis petricola','kedi-baliklari','fish','Orta','Barışçıl, sosyal','Küçük boyu ve açık renkli benekleriyle Tanganyika akvaryumlarına uygun sosyal bir kedi balığıdır. Kayalık saklanma alanlarını sever.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–9.0"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Tanganyika Gölü"], ["Ömür", "8–12 yıl"], ["Özellikler", "Tanganyika, Benekli"]]'::jsonb,array['synodontis petricola','petricola','dwarf synodontis','petricola catfish']::text[],true,'published'),
('hara-jerdoni','Asian Stone Catfish','Hara jerdoni','kedi-baliklari','fish','Orta','Barışçıl, gececi','Yaprak ve taş parçalarını andıran kamuflajıyla çok küçük bir kedi balığıdır. Sakin nano tanklarda loş ışık ve mikro yemler ister.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "18–25 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, gececi"], ["Beslenme", "Mikro canlı/dondurulmuş yem"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Hindistan–Bangladeş"], ["Ömür", "4–6 yıl"], ["Özellikler", "Nano, Kamuflaj"]]'::jsonb,array['hara jerdoni','asian stone catfish','dwarf anchor catfish','jerdoni']::text[],true,'published'),
('microglanis-iheringi','Bumblebee Catfish','Microglanis iheringi','kedi-baliklari','fish','Orta','Sakin, gececi avcı','Sarı-kahverengi bantlarıyla küçük, gece aktif bir pusu avcısıdır. Ağzına sığacak çok küçük balıklarla tutulmamalıdır.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "70 L"], ["Huy", "Sakin, gececi avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Venezuela"], ["Ömür", "5–8 yıl"], ["Özellikler", "Gececi, Küçük Avcı"]]'::jsonb,array['microglanis iheringi','bumblebee catfish','south american bumblebee catfish','microglanis']::text[],true,'published'),
('mystus-leucophasis','Upside-down Asian Catfish','Mystus leucophasis','kedi-baliklari','fish','Orta','Yarı agresif, gececi','Koyu gövdesi ve zaman zaman ters yüzme davranışıyla dikkat çeken iri bir Asya kedi balığıdır. Güçlü filtrasyon ve geniş tank gerekir.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif, gececi"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Myanmar"], ["Ömür", "10+ yıl"], ["Özellikler", "İri Kedi Balığı, Gececi"]]'::jsonb,array['upside-down asian catfish','mystus leucophasis','asian upside down catfish','black mystus','leucophasis']::text[],true,'published'),
('platydoras-armatulus','Striped Raphael Catfish','Platydoras armatulus','kedi-baliklari','fish','Kolay','Barışçıl, gececi','Zırhlı gövdesi, beyaz çizgileri ve ses çıkarabilmesiyle dayanıklı bir Güney Amerika kedi balığıdır. Gece aktiftir ve saklanma alanı ister.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, gececi"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Güney Amerika"], ["Ömür", "15+ yıl"], ["Özellikler", "Zırhlı, Gececi"]]'::jsonb,array['platydoras armatulus','striped raphael catfish','talking catfish','raphael catfish']::text[],false,'published'),
('agamyxis-pectinifrons','Spotted Raphael Catfish','Agamyxis pectinifrons','kedi-baliklari','fish','Kolay','Barışçıl, gececi','Beyaz benekli zırhlı gövdesiyle sakin, gececi bir kedi balığıdır. Gündüzleri mağara ve kök altında saklanmayı sever.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.8"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, gececi"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Amazon Havzası"], ["Ömür", "10–15 yıl"], ["Özellikler", "Benekli, Zırhlı"]]'::jsonb,array['agamyxis pectinifrons','spotted raphael catfish','spotted talking catfish','agamyxis']::text[],true,'published'),
('bunocephalus-coracoideus','Banjo Catfish','Bunocephalus coracoideus','kedi-baliklari','fish','Orta','Barışçıl, gececi','Yaprak gibi yassı vücudu ve güçlü kamuflajıyla gündüz çoğunlukla görünmeyen ilginç bir dip balığıdır. İnce kum ve loş tankları sever.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, gececi"], ["Beslenme", "Omnivor, dipten beslenen"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Amazon Havzası"], ["Ömür", "8–10 yıl"], ["Özellikler", "Kamuflaj, Gececi"]]'::jsonb,array['bunocephalus coracoideus','banjo catfish','banjo kedi balığı','coracoideus']::text[],true,'published'),
('pseudomystus-siamensis','Asian Bumblebee Catfish','Pseudomystus siamensis','kedi-baliklari','fish','Orta','Gececi, yırtıcı eğilimli','Sarımsı bantlı koyu gövdesiyle küçük-orta boy gececi Asya kedi balığıdır. Küçük balıkları avlayabileceği için tank arkadaşı seçimi önemlidir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Gececi, yırtıcı eğilimli"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Akvaryumda nadir"], ["Köken", "Güneydoğu Asya"], ["Ömür", "8–10 yıl"], ["Özellikler", "Gececi, Bantlı"]]'::jsonb,array['pseudomystus siamensis','asian bumblebee catfish','siamese bumblebee catfish','pseudomystus']::text[],true,'published'),
('otocinclus-macrospilus','Otocinclus macrospilus','Otocinclus macrospilus','kedi-baliklari','fish','Orta','Barışçıl, sosyal','Küçük boylu, alg ve biofilm tüketen sosyal bir Loricariid''dir. Yeni kurulmuş değil, oturmuş ve doğal yüzeyleri bol tanklarda daha başarılı olur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Alg, biofilm, bitkisel ek yem"], ["Üreme", "Yumurta dökücü"], ["Köken", "Peru–Kolombiya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Alg Yiyici, Sosyal"]]'::jsonb,array['otocinclus macrospilus','oto catfish','dwarf sucker','otocinclus']::text[],false,'published')
insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('fundulopanchax-sjoestedti','Blue Gularis','Fundulopanchax sjoestedti','killifishler','fish','Zor','Yarı agresif','Büyük boyu, mavi-kırmızı renkleri ve güçlü karakteriyle en gösterişli Afrika killifishlerinden biridir. İyi kapak ve canlı yem ağırlıklı beslenme ister.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Substrata yumurta bırakır"], ["Köken", "Nijerya–Kamerun"], ["Ömür", "2–3 yıl"], ["Özellikler", "İri Killi, Renkli"]]'::jsonb,array['fundulopanchax sjoestedti','blue gularis','sjoestedti','gularis killifish']::text[],true,'published'),
('fundulopanchax-walkeri','Walker''s Killi','Fundulopanchax walkeri','killifishler','fish','Orta','Yarı agresif','Sarı-kırmızı benekli erkekleriyle gösterişli bir Batı Afrika türüdür. Yumuşak su, sakin ortam ve iyi kapak tercih eder.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitki/substrata yumurta"], ["Köken", "Gana–Fildişi Sahili"], ["Ömür", "2–3 yıl"], ["Özellikler", "Renkli, Nadir Tür"]]'::jsonb,array['walker''s killi','fundulopanchax walkeri','walkeri killifish','walker killi','walkeri']::text[],true,'published'),
('fundulopanchax-nigerianus','Nigerian Killifish','Fundulopanchax nigerianus','killifishler','fish','Orta','Yarı agresif','Mavi gövde üzerindeki kırmızı çizgi ve beneklerle dikkat çeken popüler Fundulopanchax türüdür. Farklı lokalite ve renk formları bulunur.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitki/substrata yumurta"], ["Köken", "Nijerya–Kamerun"], ["Ömür", "2–3 yıl"], ["Özellikler", "Renkli, Lokal Form"]]'::jsonb,array['fundulopanchax nigerianus','nigerian killifish','nigerianus','makurdi killi']::text[],true,'published'),
('fundulopanchax-cinnamomeus','Cinnamon Killi','Fundulopanchax cinnamomeus','killifishler','fish','Zor','Yarı agresif','Tarçın-kırmızı ve mavi tonlarıyla nadir bir Kamerun killifishidir. Küçük tür tankında kontrollü üretime uygundur.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Substrata yumurta"], ["Köken", "Kamerun"], ["Ömür", "2–3 yıl"], ["Özellikler", "Nadir Tür, Renkli"]]'::jsonb,array['cinnamon killi','fundulopanchax cinnamomeus','cinnamon killifish','cinnamomeus','fundulopanchax']::text[],true,'published'),
('aphyosemion-striatum','Aphyosemion striatum','Aphyosemion striatum','killifishler','fish','Orta','Barışçıl, erkekler rekabetçi','Erkeklerin kırmızı yatay benek sıraları ve turkuaz gövdesiyle çok zarif bir türdür. Sakin, yumuşak su ve yoğun bitki örtüsü ister.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, erkekler rekabetçi"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Gabon"], ["Ömür", "2–3 yıl"], ["Özellikler", "Renkli, Küçük Killi"]]'::jsonb,array['aphyosemion striatum','striatum killifish','striped killifish','striatum']::text[],true,'published'),
('aphyosemion-bivittatum','Aphyosemion bivittatum','Aphyosemion bivittatum','killifishler','fish','Orta','Yarı agresif','Kırmızı-turuncu yüzgeçleri ve iki koyu yatay çizgisiyle dikkat çeker. Loş, bitkili ve yumuşak su akvaryumlarında iyi gelişir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "21–26 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Nijerya–Kamerun"], ["Ömür", "2–3 yıl"], ["Özellikler", "Renkli, Nadir Tür"]]'::jsonb,array['aphyosemion bivittatum','two stripe killifish','bivittatum','aphyosemion']::text[],true,'published'),
('aphyosemion-bitaeniatum','Aphyosemion bitaeniatum','Aphyosemion bitaeniatum','killifishler','fish','Orta','Yarı agresif','İki yatay çizgisi ve çok renkli yüzgeçleriyle küçük Batı Afrika killifishidir. Lokal formlar arasında belirgin renk farkları olabilir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Batı Afrika"], ["Ömür", "2–3 yıl"], ["Özellikler", "Lokal Form, Renkli"]]'::jsonb,array['aphyosemion bitaeniatum','two striped killifish','bitaeniatum','aphyosemion']::text[],true,'published'),
('aphyosemion-ogoense','Aphyosemion ogoense','Aphyosemion ogoense','killifishler','fish','Zor','Barışçıl–yarı agresif','İnce yapılı ve lokaliteye göre değişen renkleriyle koleksiyonluk bir Aphyosemion''dur. Saf lokalite hatlarının karıştırılmaması önemlidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Kongo–Gabon"], ["Ömür", "2–3 yıl"], ["Özellikler", "Lokal Form, Nadir Tür"]]'::jsonb,array['aphyosemion ogoense','ogoense killifish','ogoense','aphyosemion']::text[],true,'published'),
('nothobranchius-guentheri','Nothobranchius guentheri','Nothobranchius guentheri','killifishler','fish','Orta','Yarı agresif','Mavi gövde, kırmızı benekler ve kırmızı kuyrukla çok gösterişli yıllık killifishidir. Yumurtalar kuru dönem diyapozu geçirir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Tanzanya"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Renkli"]]'::jsonb,array['nothobranchius guentheri','guentheri killifish','guentheri','notho']::text[],true,'published'),
('nothobranchius-korthausae','Nothobranchius korthausae','Nothobranchius korthausae','killifishler','fish','Orta','Yarı agresif','Kırmızı ve sarı renk formlarıyla tanınan küçük yıllık killifishidir. Torf veya uygun yumurtlama substratıyla üretilebilir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "35 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Tanzanya, Mafia Adası"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Lokal Form"]]'::jsonb,array['nothobranchius korthausae','korthausae','mafia island killifish','notho']::text[],true,'published'),
('nothobranchius-eggersi','Nothobranchius eggersi','Nothobranchius eggersi','killifishler','fish','Zor','Yarı agresif','Yoğun kırmızı veya mavi lokal formlarıyla en çarpıcı Nothobranchius türlerindendir. Yıllık yaşam döngüsü nedeniyle yumurta inkübasyonu bakımın parçasıdır.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "35 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Tanzanya"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Nadir Tür"]]'::jsonb,array['nothobranchius eggersi','eggersi killifish','red eggersi','notho eggersi']::text[],true,'published'),
('nothobranchius-furzeri','Nothobranchius furzeri','Nothobranchius furzeri','killifishler','fish','Zor','Yarı agresif','Turkuaz ve kırmızı erkekleriyle tanınan, geçici havuzlarda yaşayan yıllık bir killifishidir. Çok kısa yaşam döngüsü nedeniyle bilimsel araştırmalarda da model organizma olarak kullanılır.','[["Yetişkin boy", "6,5 cm"], ["Sıcaklık", "23–30 °C"], ["pH", "6.5–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık; çamur/substrata yumurta"], ["Köken", "Zimbabwe–Mozambik bölgesi"], ["Ömür", "Birkaç ay–1 yıl"], ["Özellikler", "Yıllık Killi, Kısa Ömür"]]'::jsonb,array['nothobranchius furzeri','turquoise killifish','african turquoise killifish','furzeri']::text[],true,'published'),
('nothobranchius-kilomberoensis','Nothobranchius kilomberoensis','Nothobranchius kilomberoensis','killifishler','fish','Zor','Yarı agresif','Mavi-yeşil gövde ve kırmızı desenlerle dikkat çeken Tanzanya kökenli yıllık killifishidir. Üretimde kuru inkübasyon süresi kritik rol oynar.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "35 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Tanzanya"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Nadir Tür"]]'::jsonb,array['nothobranchius kilomberoensis','kilombero killifish','kilomberoensis','notho']::text[],true,'published'),
('nothobranchius-palmqvisti','Nothobranchius palmqvisti','Nothobranchius palmqvisti','killifishler','fish','Orta','Yarı agresif','Kırmızı benekli mavi gövdesiyle klasik yıllık Afrika killifishlerinden biridir. Geçici su birikintilerinin yaşam döngüsüne uyum sağlamıştır.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Kenya–Tanzanya"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Renkli"]]'::jsonb,array['nothobranchius palmqvisti','palmqvisti killifish','palmqvisti','notho']::text[],true,'published'),
('epiplatys-annulatus','Clown Killifish','Epiplatys annulatus','killifishler','fish','Orta','Barışçıl, yüzeyci','Küçük boyu, bantlı gövdesi ve roket biçimli renkli kuyruğuyla nano akvaryumların özel türlerindendir. Yüzeyde yaşar ve çok iyi sıçrar.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "4.5–7.0"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, yüzeyci"], ["Beslenme", "Mikro canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Batı Afrika"], ["Ömür", "2–3 yıl"], ["Özellikler", "Nano, Yüzey Balığı"]]'::jsonb,array['epiplatys annulatus','clown killifish','rocket killifish','annulatus']::text[],false,'published'),
('epiplatys-dageti','Epiplatys dageti','Epiplatys dageti','killifishler','fish','Orta','Yarı agresif, yüzeyci','Yüzeyde yaşayan, bantlı ve dayanıklı sayılabilecek Batı Afrika killifishidir. Sıkı kapak ve yüzen bitkiler bakımda önemlidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif, yüzeyci"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Batı Afrika"], ["Ömür", "2–3 yıl"], ["Özellikler", "Yüzey Balığı, Renkli"]]'::jsonb,array['epiplatys dageti','dageti killifish','red chin panchax','dageti']::text[],true,'published'),
('aplocheilus-lineatus','Golden Wonder Panchax','Aplocheilus lineatus','killifishler','fish','Kolay','Yarı agresif, avcı','Altın ticari formuyla çok tanınan, yüzeyde yaşayan iri bir killifishidir. Küçük balıkları avlayabilir ve güçlü biçimde sıçrar.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif, avcı"], ["Beslenme", "Omnivor, etçil eğilimli"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Hindistan–Sri Lanka"], ["Ömür", "3–5 yıl"], ["Özellikler", "Yüzey Balığı, Avcı"]]'::jsonb,array['golden wonder panchax','aplocheilus lineatus','golden wonder','striped panchax','golden wonder killifish']::text[],false,'published'),
('aplocheilus-panchax','Blue Panchax','Aplocheilus panchax','killifishler','fish','Kolay','Yarı agresif, yüzeyci','Mavi yansımaları olan, yüzeyde yaşayan dayanıklı bir Asya killifishidir. Küçük tank arkadaşlarını avlayabileceğinden boy seçimi önemlidir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "22–30 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif, yüzeyci"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Güney ve Güneydoğu Asya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Yüzey Balığı, Dayanıklı"]]'::jsonb,array['aplocheilus panchax','blue panchax','panchax','blue killifish']::text[],false,'published'),
('poropanchax-normani','Norman Lampeye','Poropanchax normani','killifishler','fish','Kolay','Barışçıl, sürü balığı','Parlak mavi gözleri ve küçük boyuyla zarif bir Afrika sürü killifishidir. Klasik çift/trio killilerden farklı olarak kalabalık grup hâlinde tutulur.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, sürü balığı"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Batı Afrika"], ["Ömür", "2–3 yıl"], ["Özellikler", "Mavi Gözlü, Sürü Balığı"]]'::jsonb,array['norman lampeye','poropanchax normani','normans lampeye','lampeye killifish','normani']::text[],false,'published'),
('procatopus-aberrans','Procatopus aberrans','Procatopus aberrans','killifishler','fish','Zor','Barışçıl, aktif sürü','Metalik mavi gövdesi ve hızlı yüzüşüyle akıntılı Batı Afrika sularına uyumlu bir lampeye türüdür. Oksijenli ve uzun tank tercih eder.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, aktif sürü"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Yarık/bitkilere yumurta"], ["Köken", "Kamerun"], ["Ömür", "3–4 yıl"], ["Özellikler", "Mavi Gözlü, Akıntı Seven"]]'::jsonb,array['procatopus aberrans','aberrans lampeye','procatopus','lampeye']::text[],true,'published'),
('oryzias-woworae','Oryzias woworae','Oryzias woworae','killifishler','fish','Orta','Barışçıl, sosyal','Elektrik mavisi gövde ve kırmızı yüzgeçleriyle çok renkli küçük bir medakadır. Bitkili tanklarda grup hâlinde tutulabilir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Bitkilere yapışık yumurta"], ["Köken", "Sulawesi, Endonezya"], ["Ömür", "3–4 yıl"], ["Özellikler", "Nano, Mavi"]]'::jsonb,array['oryzias woworae','daisy ricefish','woworae','neon ricefish']::text[],true,'published'),
('oryzias-latipes','Japanese Ricefish / Medaka','Oryzias latipes','killifishler','fish','Kolay','Barışçıl, sosyal','Serin su toleransı, çok sayıda renk formu ve kolay üretimiyle popüler bir medakadır. Yumurtaları dişinin karnında kısa süre taşınıp bitkilere bırakılır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "15–28 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, sosyal"], ["Beslenme", "Omnivor"], ["Üreme", "Bitkilere yapışık yumurta"], ["Köken", "Doğu Asya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Serin Su, Kolay Üretim"]]'::jsonb,array['japanese ricefish / medaka','oryzias latipes','medaka','japanese ricefish','japon pirinç balığı']::text[],false,'published'),
('jordanella-floridae','American Flagfish','Jordanella floridae','killifishler','fish','Orta','Yarı agresif, bölgeci','Bayrak benzeri kırmızı-mavi desenleri ve alg yeme eğilimiyle farklı bir Kuzey Amerika killifishidir. Erkekler üreme döneminde bölgeci olabilir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "18–26 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "70 L"], ["Huy", "Yarı agresif, bölgeci"], ["Beslenme", "Omnivor, bitkisel katkılı"], ["Üreme", "Substrata yumurta"], ["Köken", "Florida, ABD"], ["Ömür", "3–5 yıl"], ["Özellikler", "Alg Yiyici, Renkli"]]'::jsonb,array['jordanella floridae','american flagfish','florida flagfish','flag fish']::text[],true,'published'),
('fundulus-chrysotus','Florida Golden Topminnow','Fundulus chrysotus','killifishler','fish','Orta','Yarı agresif, yüzeyci','Altın benekleriyle dikkat çeken dayanıklı Kuzey Amerika killifishidir. Serin-tropikal aralıkta yaşayabilir ve yüzeyde aktiftir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "15–28 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "80 L"], ["Huy", "Yarı agresif, yüzeyci"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Bitkilere yumurta"], ["Köken", "ABD"], ["Ömür", "3–5 yıl"], ["Özellikler", "Serin Su, Yüzey Balığı"]]'::jsonb,array['florida golden topminnow','fundulus chrysotus','golden topminnow','goldspotted killifish','chrysotus']::text[],true,'published'),
('austrolebias-nigripinnis','Black Pearl Killifish','Austrolebias nigripinnis','killifishler','fish','Zor','Yarı agresif','Koyu gövde üzerindeki parlak mavi benekleriyle çok çarpıcı yıllık Güney Amerika killifishidir. Serin su ve kuru yumurta inkübasyonu ister.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "15–24 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Arjantin–Uruguay"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Serin Su"]]'::jsonb,array['austrolebias nigripinnis','black pearl killifish','nigripinnis','austrolebias']::text[],true,'published'),
('hypsolebias-constanciae','Simpsonichthys constanciae','Hypsolebias constanciae','killifishler','fish','Zor','Yarı agresif','Kırmızı-mavi desenleriyle küçük ve özel bir Brezilya yıllık killifishidir. Geçici habitat yaşam döngüsü nedeniyle yumurtaları kuru inkübasyon ister.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "35 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Brezilya"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Nadir Tür"]]'::jsonb,array['hypsolebias constanciae','simpsonichthys constanciae','constanciae killifish','constanciae']::text[],true,'published'),
('pterolebias-longipinnis','Pterolebias longipinnis','Pterolebias longipinnis','killifishler','fish','Zor','Yarı agresif','Uzun yüzgeçli, iri sayılabilecek yıllık Güney Amerika killifishidir. Mevsimsel habitatlara uyumlu yumurtaları diyapoz geçirir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "70 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Güney Amerika"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Uzun Yüzgeç"]]'::jsonb,array['pterolebias longipinnis','longfin annual killifish','pterolebias','longipinnis']::text[],true,'published'),
('kryptolebias-cylindraceus','Rivulus cylindraceus','Kryptolebias cylindraceus','killifishler','fish','Zor','Yarı agresif','Küba kökenli, ince yapılı ve sıçrama yeteneği yüksek bir rivulus türüdür. Sığ, kapaklı ve bol saklanmalı tanklarda tutulmalıdır.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere/substrata yumurta"], ["Köken", "Küba"], ["Ömür", "3–4 yıl"], ["Özellikler", "Rivulus, Nadir Tür"]]'::jsonb,array['kryptolebias cylindraceus','rivulus cylindraceus','cuban rivulus','cylindraceus']::text[],true,'published'),
('kryptolebias-marmoratus','Mangrove Rivulus','Kryptolebias marmoratus','killifishler','fish','Zor','Yarı agresif, özel tür','Hem çevresel toleransı hem de kendini dölleyebilen hermafrodit bireyleriyle biyolojik olarak sıra dışı bir killifishidir. Acı suya kadar geniş tuzluluk aralığında yaşayabilir.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "20–30 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif, özel tür"], ["Beslenme", "Omnivor"], ["Üreme", "Kendini dölleme dahil iç döllenme/yumurta"], ["Köken", "Atlantik mangrovları"], ["Ömür", "3–5 yıl"], ["Özellikler", "Özel Üreme, Mangrov"]]'::jsonb,array['kryptolebias marmoratus','mangrove rivulus','mangrove killifish','marmoratus']::text[],true,'published'),
('austrofundulus-limnaeus','Austrofundulus limnaeus','Austrofundulus limnaeus','killifishler','fish','Zor','Yarı agresif','Venezuela''nın geçici havuzlarına uyum sağlamış yıllık bir killifishidir. Embriyoları uzun diyapoz dönemlerine dayanabilir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "23–29 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Yıllık, tabana yumurta"], ["Köken", "Venezuela"], ["Ömür", "1 yıl civarı"], ["Özellikler", "Yıllık Killi, Nadir Tür"]]'::jsonb,array['austrofundulus limnaeus','annual killifish','limnaeus','austrofundulus']::text[],true,'published'),
('lucania-goodei','Lucania goodei','Lucania goodei','killifishler','fish','Orta','Barışçıl–yarı agresif','Mavi yüzgeçli küçük Kuzey Amerika killifishidir. Serin, temiz ve bitkili tanklarda grup hâlinde bakılabilir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "18–27 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Omnivor, böcekçil"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Florida, ABD"], ["Ömür", "3–4 yıl"], ["Özellikler", "Mavi Yüzgeç, Serin Su"]]'::jsonb,array['lucania goodei','bluefin killifish','goodei','lucania']::text[],true,'published'),
('fundulopanchax-filamentosus','Fundulopanchax filamentosus','Fundulopanchax filamentosus','killifishler','fish','Zor','Yarı agresif','Erkeklerde uzayan yüzgeç ışınları ve canlı kırmızı-mavi desenlerle gösterişli bir türdür. İyi kapak ve kaliteli canlı yemlerle başarılı olur.','[["Yetişkin boy", "7 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "50 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Substrata yumurta"], ["Köken", "Batı Afrika"], ["Ömür", "2–3 yıl"], ["Özellikler", "Uzun Yüzgeç, Nadir Tür"]]'::jsonb,array['fundulopanchax filamentosus','filamentosus killifish','filamentosus','fundulopanchax']::text[],true,'published'),
('aphyosemion-gabunense','Aphyosemion gabunense','Aphyosemion gabunense','killifishler','fish','Zor','Barışçıl–yarı agresif','Gabon kökenli, farklı lokalite formlarında kırmızı ve mavi desenler gösteren zarif bir killifishidir. Saf lokalite üretimi koleksiyoncular için önemlidir.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "21–26 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl–yarı agresif"], ["Beslenme", "Canlı/dondurulmuş yem"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Gabon"], ["Ömür", "2–3 yıl"], ["Özellikler", "Lokal Form, Nadir Tür"]]'::jsonb,array['aphyosemion gabunense','gabunense killifish','gabon killifish','gabunense']::text[],true,'published'),
('epiplatys-sexfasciatus','Epiplatys sexfasciatus','Epiplatys sexfasciatus','killifishler','fish','Orta','Yarı agresif, yüzey avcısı','Altı bantlı gövdesi ve yüzey avcısı davranışıyla iri bir Epiplatys türüdür. Küçük balıkları avlayabileceğinden tank arkadaşı seçimi önemlidir.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "90 L"], ["Huy", "Yarı agresif, yüzey avcısı"], ["Beslenme", "Etçil ağırlıklı omnivor"], ["Üreme", "Bitkilere yumurta"], ["Köken", "Batı–Orta Afrika"], ["Ömür", "3–4 yıl"], ["Özellikler", "Yüzey Balığı, Bantlı"]]'::jsonb,array['epiplatys sexfasciatus','six barred panchax','sexfasciatus','epiplatys']::text[],true,'published')
insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('melanotaenia-praecox','Cüce Neon Gökkuşağı','Melanotaenia praecox','gokkusaklari','fish','Kolay','Barışçıl, hareketli','Küçük boyuna rağmen çok hareketli ve parlak mavi gövdeli bir sürü balığıdır.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Bitkilere/yumurtlama mopuna yumurta saçar"], ["Köken", "Yeni Gine"], ["Ömür", "4–5 yıl"], ["Özellikler", "Sürü, aktif, renkli"]]'::jsonb,array['praecox','cüce neon gökkuşağı','dwarf neon rainbowfish']::text[],false,'published'),
('melanotaenia-lacustris','Turkuaz Gökkuşağı','Melanotaenia lacustris','gokkusaklari','fish','Orta','Barışçıl, aktif','Kutubu Gölü kökenli, erişkin erkekleri yoğun turkuaz-mavi renk alan gösterişli bir türdür.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Papua Yeni Gine, Kutubu Gölü"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, mavi, aktif"]]'::jsonb,array['lacustris','turkuaz gökkuşağı','lake kutubu rainbowfish']::text[],false,'published'),
('melanotaenia-trifasciata','Bantlı Gökkuşağı','Melanotaenia trifasciata','gokkusaklari','fish','Orta','Barışçıl, çok hareketli','Çok sayıda coğrafi varyetesi bulunan, iri ve son derece renkli bir Avustralya gökkuşağıdır.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, çok hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Kuzey Avustralya"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sürü, iri, renkli"]]'::jsonb,array['trifasciata','bantlı gökkuşağı','banded rainbowfish']::text[],false,'published'),
('glossolepis-incisus','Kırmızı Gökkuşağı','Glossolepis incisus','gokkusaklari','fish','Orta','Barışçıl, aktif','Erkekleri erişkinlikte güçlü kırmızı renk geliştiren, geniş yüzme alanı isteyen iri bir gökkuşağıdır.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "220 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Yeni Gine, Sentani Gölü"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sürü, kırmızı, iri"]]'::jsonb,array['incisus','kırmızı gökkuşağı','red rainbowfish']::text[],false,'published'),
('melanotaenia-parkinsoni','Parkinson Gökkuşağı','Melanotaenia parkinsoni','gokkusaklari','fish','Orta','Barışçıl, hareketli','Gümüş gövdesindeki sarı-turuncu alanlarla dikkat çeken hareketli bir sürü balığıdır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl, hareketli"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Papua Yeni Gine"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, turuncu, aktif"]]'::jsonb,array['parkinsoni','parkinson gökkuşağı','parkinson rainbowfish']::text[],true,'published'),
('melanotaenia-herbertaxelrodi','Herbert Axelrod Gökkuşağı','Melanotaenia herbertaxelrodi','gokkusaklari','fish','Orta','Barışçıl','Sarı-altın gövdesi ve koyu orta çizgisiyle tanınan, orta boy bir gökkuşağıdır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Papua Yeni Gine, Tebera Gölü"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, sarı, aktif"]]'::jsonb,array['herbert axelrod gökkuşağı','herbertaxelrodi','axelrod gökkuşağı','lake tebera rainbowfish']::text[],true,'published'),
('melanotaenia-affinis','Yeni Gine Gökkuşağı','Melanotaenia affinis','gokkusaklari','fish','Kolay','Barışçıl, aktif','Farklı popülasyonları değişken renk ve desen gösterebilen dayanıklı bir Yeni Gine türüdür.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Yeni Gine"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, dayanıklı, aktif"]]'::jsonb,array['affinis','yeni gine gökkuşağı','new guinea rainbowfish']::text[],false,'published'),
('melanotaenia-fluviatilis','Avustralya Gökkuşağı','Melanotaenia fluviatilis','gokkusaklari','fish','Kolay','Barışçıl, aktif','Serin sayılabilecek koşullara da uyum sağlayabilen, iri ve dayanıklı bir Avustralya türüdür.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "20–27 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "220 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Doğu Avustralya"], ["Ömür", "5–8 yıl"], ["Özellikler", "Sürü, iri, dayanıklı"]]'::jsonb,array['fluviatilis','avustralya gökkuşağı','australian rainbowfish']::text[],true,'published'),
('chilatherina-bleheri','Bleher Gökkuşağı','Chilatherina bleheri','gokkusaklari','fish','Orta','Barışçıl, aktif','Yüksek sırt yapısı ve erişkin erkeklerdeki sarı-kırmızı tonlarıyla dikkat çeken zarif bir türdür.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "180 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Batı Yeni Gine"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, renkli, özel"]]'::jsonb,array['bleheri','bleher gökkuşağı','bleher''s rainbowfish']::text[],true,'published'),
('iriatherina-werneri','İplik Yüzgeçli Gökkuşağı','Iriatherina werneri','gokkusaklari','fish','Orta','Barışçıl, narin','Erkeklerin uzamış yüzgeçleri ve zarif kur davranışlarıyla tanınan küçük, hassas bir türdür.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, narin"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Bitkilere ince yumurtalar bırakır"], ["Köken", "Yeni Gine ve kuzey Avustralya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Narin, sürü, uzun yüzgeç"]]'::jsonb,array['iplik yüzgeçli gökkuşağı','werneri','iriatherina','threadfin rainbowfish']::text[],false,'published'),
('pseudomugil-gertrudae','Benekli Mavi Göz','Pseudomugil gertrudae','gokkusaklari','fish','Orta','Barışçıl, narin','Benekli yüzgeçleri ve erkeklerin gösterişli kur davranışlarıyla sevilen küçük bir mavi-göz türüdür.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.5–7.5"], ["Min. akvaryum", "45 L"], ["Huy", "Barışçıl, narin"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Mop/bitkilere yumurta bırakır"], ["Köken", "Yeni Gine ve kuzey Avustralya"], ["Ömür", "2–4 yıl"], ["Özellikler", "Nano, sürü, mavi göz"]]'::jsonb,array['gertrudae','spotted blue-eye','benekli mavi göz']::text[],false,'published'),
('pseudomugil-luminatus','Kırmızı Neon Mavi Göz','Pseudomugil luminatus','gokkusaklari','fish','Orta','Barışçıl, hareketli','Kırmızı-turuncu gövdesi ve mavi gözleriyle nano akvaryumların en dikkat çekici türlerinden biridir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.5"], ["Min. akvaryum", "45 L"], ["Huy", "Barışçıl, hareketli"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Mop/bitkilere yumurta bırakır"], ["Köken", "Güney Yeni Gine"], ["Ömür", "2–4 yıl"], ["Özellikler", "Nano, kırmızı, sürü"]]'::jsonb,array['luminatus','red neon blue-eye','kırmızı neon mavi göz']::text[],true,'published'),
('pseudomugil-signifer','Pasifik Mavi Göz','Pseudomugil signifer','gokkusaklari','fish','Orta','Barışçıl, aktif','Tatlı sudan hafif acı suya kadar farklı habitatlarda görülebilen küçük ve aktif bir türdür.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.2"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Mop/bitkilere yumurta bırakır"], ["Köken", "Doğu Avustralya"], ["Ömür", "3–4 yıl"], ["Özellikler", "Sürü, mavi göz, kıyısal"]]'::jsonb,array['signifer','pacific blue-eye','pasifik mavi göz']::text[],true,'published'),
('pseudomugil-cyanodorsalis','Neon Mavi Göz','Pseudomugil cyanodorsalis','gokkusaklari','fish','Zor','Barışçıl, hassas','Özellikle acı suya uyumlu popülasyonlarıyla bilinen, minik ve parlak mavi yüzgeçli bir türdür.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "45 L"], ["Huy", "Barışçıl, hassas"], ["Beslenme", "Mikro omnivor"], ["Üreme", "Mop/bitkilere yumurta bırakır"], ["Köken", "Kuzey Avustralya"], ["Ömür", "2–3 yıl"], ["Özellikler", "Nano, acı su, mavi göz"]]'::jsonb,array['neon mavi göz','cyanodorsalis','neon blue-eye','blueback blue-eye']::text[],true,'published'),
('marosatherina-ladigesi','Celebes Gökkuşağı','Marosatherina ladigesi','gokkusaklari','fish','Orta','Barışçıl, aktif','Şeffaf gövdesi, sarı yüzgeçleri ve mavi gözleriyle Sulawesi kökenli zarif bir türdür.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "90 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Bitkilere yumurta bırakır"], ["Köken", "Sulawesi, Endonezya"], ["Ömür", "4–5 yıl"], ["Özellikler", "Sürü, zarif, Sulawesi"]]'::jsonb,array['ladigesi','celebes rainbowfish','celebes gökkuşağı']::text[],false,'published'),
('bedotia-madagascariensis','Madagaskar Gökkuşağı','Bedotia madagascariensis','gokkusaklari','fish','Orta','Barışçıl, aktif','Madagaskar''a özgü, uzun gövdeli ve aktif bir sürü balığıdır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Yumurta saçar"], ["Köken", "Madagaskar"], ["Ömür", "5–7 yıl"], ["Özellikler", "Sürü, aktif, Madagaskar"]]'::jsonb,array['bedotia','madagascariensis','madagaskar gökkuşağı']::text[],true,'published')
