('dichotomyctere-ocellatus','Sekiz Figürlü Balon','Dichotomyctere ocellatus','aci-su','fish','Zor','Bölgeci, meraklı','Karmaşık desenli, karakterli ve dişleri sürekli büyüyen gerçek acı su balonlarından biridir.','[["Yetişkin boy", "8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "80 L"], ["Huy", "Bölgeci, meraklı"], ["Beslenme", "Kabuklu/sert omurgasız"], ["Üreme", "Akvaryumda üretimi çok güç"], ["Köken", "Güneydoğu Asya"], ["Ömür", "8–12 yıl"], ["Özellikler", "Balon, acı su, salyangoz"]]'::jsonb,array['figure 8 puffer','ocellatus','sekiz figürlü balon']::text[],false,'published'),
('etroplus-suratensis','Yeşil Kromid','Etroplus suratensis','aci-su','fish','Zor','Yarı agresif, sosyal','İri boyutlu, sürü eğilimli ve acı suya iyi uyum sağlayan Güney Asya cikletidir.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "450 L"], ["Huy", "Yarı agresif, sosyal"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Hindistan ve Sri Lanka"], ["Ömür", "8–12 yıl"], ["Özellikler", "İri, ciklet, acı su"]]'::jsonb,array['green chromide','suratensis','yeşil kromid']::text[],true,'published'),
('etroplus-maculatus','Turuncu Kromid','Etroplus maculatus','aci-su','fish','Orta','Yarı agresif','Küçük boylu, sarı-turuncu renkli ve uygun eşlerle bakıldığında ilginç ebeveyn davranışları gösteren bir ciklettir.','[["Yetişkin boy", "9 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı, ebeveyn bakımı"], ["Köken", "Hindistan ve Sri Lanka"], ["Ömür", "5–8 yıl"], ["Özellikler", "Ciklet, acı su, turuncu"]]'::jsonb,array['orange chromide','maculatus','turuncu kromid']::text[],true,'published'),
('toxotes-jaculatrix','Okçu Balığı','Toxotes jaculatrix','aci-su','fish','Zor','Yırtıcı, sosyal','Su üzerindeki böcekleri su püskürterek düşürmesiyle ünlü, geniş yüzey alanı isteyen özel bir acı su balığıdır.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "350 L"], ["Huy", "Yırtıcı, sosyal"], ["Beslenme", "Böcekçil/etçil"], ["Üreme", "Akvaryum üretimi zordur"], ["Köken", "Güney ve Güneydoğu Asya"], ["Ömür", "8–12 yıl"], ["Özellikler", "Okçu, acı su, yırtıcı"]]'::jsonb,array['archerfish','jaculatrix','okçu balığı']::text[],true,'published'),
('monodactylus-argenteus','Gümüş Mono','Monodactylus argenteus','aci-su','fish','Zor','Barışçıl, çok aktif','Gençken acı suda, erişkinlikte daha yüksek tuzlulukta tutulabilen hızlı ve iri sürü balığıdır.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl, çok aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryumda nadiren ürer"], ["Köken", "Hint-Pasifik kıyıları"], ["Ömür", "7–10 yıl"], ["Özellikler", "Sürü, acı su, iri"]]'::jsonb,array['silver mono','argenteus','gümüş mono']::text[],false,'published'),
('monodactylus-sebae','Afrika Mono','Monodactylus sebae','aci-su','fish','Zor','Barışçıl, aktif','Yüksek gövdeli siyah-gümüş deseniyle tanınan, grup halinde tutulması gereken iri bir acı su türüdür.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "450 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Akvaryum üretimi çok nadir"], ["Köken", "Batı Afrika kıyıları"], ["Ömür", "7–10 yıl"], ["Özellikler", "Sürü, acı su, Afrika"]]'::jsonb,array['sebae','african mono','afrika mono']::text[],true,'published'),
('scatophagus-argus','Benekli Scat','Scatophagus argus','aci-su','fish','Zor','Sosyal, hareketli','İştahlı, iri ve dayanıklı; erişkinliğe doğru daha yüksek tuzluluk isteyen klasik acı su balıklarındandır.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "450 L"], ["Huy", "Sosyal, hareketli"], ["Beslenme", "Omnivor, bitkisel katkı önemli"], ["Üreme", "Akvaryumda üretimi güç"], ["Köken", "Hint-Pasifik"], ["Ömür", "10+ yıl"], ["Özellikler", "Scat, acı su, iri"]]'::jsonb,array['spotted scat','argus','benekli scat']::text[],false,'published'),
('ariopsis-seemanni','Kolombiya Köpekbalığı Kedi Balığı','Ariopsis seemanni','aci-su','fish','Zor','Sosyal, yırtıcı','Gençken tatlı/acımtrak suda satılsa da büyüdükçe deniz seviyesine yaklaşan tuzluluk ve çok büyük hacim ister.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "600 L"], ["Huy", "Sosyal, yırtıcı"], ["Beslenme", "Etçil/omnivor"], ["Üreme", "Ağızda kuluçka"], ["Köken", "Orta Amerika''nın Pasifik kıyıları"], ["Ömür", "10–15 yıl"], ["Özellikler", "Kedi balığı, acı su, iri"]]'::jsonb,array['kolombiya köpekbalığı kedi balığı','colombian shark catfish','seemanni','kolombiya köpekbalığı']::text[],true,'published'),
('brachygobius-doriae','Bumblebee Goby','Brachygobius doriae','gobyler','fish','Orta','Bölgeci ama küçük','Sarı-siyah bantlı, dipte yaşayan ve küçük canlı/dondurulmuş yemleri tercih eden minik bir gobidir.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "40 L"], ["Huy", "Bölgeci ama küçük"], ["Beslenme", "Mikro etçil"], ["Üreme", "Mağara/yüzeye yumurta bırakır"], ["Köken", "Güneydoğu Asya"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano, goby, acı su"]]'::jsonb,array['bumblebee goby','brachygobius','doriae']::text[],false,'published'),
