('periophthalmus-barbarus','Çamur Zıpzıpı','Periophthalmus barbarus','gobyler','fish','Zor','Bölgeci','Karada da hareket edebilen amfibi yaşam tarzıyla sıra dışı; akvaryumdan çok paludaryum isteyen bir türdür.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "200 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil/omnivor"], ["Üreme", "Esaret üretimi zordur"], ["Köken", "Batı Afrika kıyıları"], ["Ömür", "5–8 yıl"], ["Özellikler", "Paludaryum, amfibi, acı su"]]'::jsonb,array['mudskipper','barbarus','çamur zıpzıpı']::text[],true,'published'),
('anableps-anableps','Dört Gözlü Balık','Anableps anableps','aci-su','fish','Zor','Sosyal, aktif','Göz yapısı sayesinde suyun hem üstünü hem altını aynı anda görebilen, yüzeyde yaşayan çok özel bir acı su balığıdır.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "500 L"], ["Huy", "Sosyal, aktif"], ["Beslenme", "Omnivor"], ["Üreme", "Canlı doğuran"], ["Köken", "Kuzey Güney Amerika kıyıları"], ["Ömür", "6–10 yıl"], ["Özellikler", "Yüzey, canlı doğuran, acı su"]]'::jsonb,array['four-eyed fish','anableps','dört gözlü balık']::text[],true,'published'),
('poecilia-latipinna','Yelken Yüzgeçli Molly','Poecilia latipinna','aci-su','fish','Kolay','Barışçıl, aktif','Sert ve mineralce zengin sularda gelişen, erkekleri büyük sırt yüzgeci taşıyan canlı doğurandır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor, alg/bitkisel"], ["Üreme", "Canlı doğuran"], ["Köken", "Kuzey Amerika kıyı havzaları"], ["Ömür", "3–5 yıl"], ["Özellikler", "Canlı doğuran, sert su, yelken"]]'::jsonb,array['sailfin molly','latipinna','yelken yüzgeçli molly']::text[],false,'published'),
('poecilia-velifera','Yucatan Molly','Poecilia velifera','aci-su','fish','Orta','Barışçıl, aktif','Çok büyük yelken biçimli sırt yüzgeciyle tanınan, sert ve alkali suyu seven iri bir molly türüdür.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.2–8.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, aktif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Canlı doğuran"], ["Köken", "Yucatán Yarımadası"], ["Ömür", "3–5 yıl"], ["Özellikler", "Canlı doğuran, yelken, sert su"]]'::jsonb,array['velifera','yucatan molly','dev yelken molly']::text[],false,'published')
